describe('WatchlistStore.clearWatched()', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('removes every watched movie and keeps unwatched ones in order', () => {
    const store = new WatchlistStore();
    store.add(mk(1, 'A'));
    store.add(mk(2, 'B'));
    store.add(mk(3, 'C'));
    store.add(mk(4, 'D'));
    store.toggleWatched(2);
    store.toggleWatched(4);

    store.clearWatched();

    expect(store.items().map((item) => item.id)).toEqual([1, 3]);
    expect(store.count()).toBe(2);
    expect(store.watchedCount()).toBe(0);
  });

  it('is a no-op when nothing is watched', () => {
    const store = new WatchlistStore();
    store.add(mk(1, 'A'));
    store.add(mk(2, 'B'));

    store.clearWatched();

    expect(store.items().map((item) => item.id)).toEqual([1, 2]);
    expect(store.watchedCount()).toBe(0);
    expect(store.count()).toBe(2);
  });

