import { TestBed } from '@angular/core/testing';
import { WatchlistStore } from './watchlist-store';
import { TmdbMovie } from './movie';

// Keeps a watchlist store's asynchronous persistence effect (which writes to
// localStorage) a chance to run before assertions.
const flushEffects = () => new Promise<void>(resolve => setTimeout(resolve, 0));

const movie = (id: number): TmdbMovie => ({
    id,
    title: `Movie ${id}`,
    release_date: '2024-01-01',
    poster_path: `/poster-${id}.jpg`,
    overview: 'A movie',
});

describe('WatchlistStore', () => {
  let service: WatchlistStore;

  // Runs before the original beforeEach so each spec starts with a clean
  // localStorage backing store.
  beforeEach(() => {
    localStorage.clear();
  });

  beforeEach(() => {
    TestBed.configureTestingModule({});
    service = TestBed.inject(WatchlistStore);
  });

  it('should be created', () => {
    expect(service).toBeTruthy();
  });

  it('clearWatched() removes watched items, keeps unwatched ones in order and updates the derived signals', () => {
    [1, 2, 3, 4].forEach(id => service.add(movie(id)));
    service.toggleWatched(2);
    service.toggleWatched(4);

    service.clearWatched();

    expect(service.items().map(m => m.id)).toEqual([1, 3]);
    expect(service.count()).toBe(2);
    expect(service.watchedCount()).toBe(0);
  });

  it('clearWatched() persists the cleared state so a fresh store sees it', async () => {
    service.add(movie(1));
    service.add(movie(2));
    service.toggleWatched(1);

    service.clearWatched();
    await flushEffects();

    const persisted = JSON.parse(localStorage.getItem('watchlist') ?? '[]');
    expect(persisted.map((m: { id: number }) => m.id)).toEqual([2]);

    const fresh = TestBed.runInInjectionContext(() => new WatchlistStore());
    expect(fresh.items().map(m => m.id)).toEqual([2]);
    expect(fresh.count()).toBe(1);
    expect(fresh.watchedCount()).toBe(0);
  });

  it('clearWatched() is a harmless no-op when nothing is watched or the list is empty', async () => {
    const before = service.items();
    service.clearWatched();
    expect(service.items()).toBe(before);
    expect(service.count()).toBe(0);
    expect(service.watchedCount()).toBe(0);

    service.add(movie(7));
    service.clearWatched();
    expect(service.items().map(m => m.id)).toEqual([7]);
    expect(service.count()).toBe(1);
    expect(service.watchedCount()).toBe(0);

    await flushEffects();
    expect(JSON.parse(localStorage.getItem('watchlist') ?? '[]')).toEqual([
      { id: 7, title: 'Movie 7', poster_path: '/poster-7.jpg', release_date: '2024-01-01', watched: false },
    ]);
  });
});

